import {Injectable} from '@angular/core';
import {HttpErrorResponse, HttpEvent, HttpHandler, HttpInterceptor, HttpRequest, HttpXsrfTokenExtractor} from '@angular/common/http';
import {catchError} from 'rxjs/operators';
import {Observable, throwError} from 'rxjs';
import {EMPTY} from 'rxjs';
import {Router} from '@angular/router';

@Injectable()
export class CustomInterceptor implements HttpInterceptor {

    constructor(
        private tokenService: HttpXsrfTokenExtractor, private router: Router
    ) {

    }

    intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {

        /*request = request.clone({
            withCredentials: true
        });*/

        const lcUrl = req.url.toLowerCase();
        // Skip both non-mutating requests and absolute URLs.
        // Non-mutating requests don't require a token, and absolute URLs require special handling
        // anyway as the cookie set
        // on our origin is not the same as the token expected by another origin.
        if (req.method === 'GET' || req.method === 'HEAD' || lcUrl.startsWith('http://')) {
            return next.handle(req).pipe(
                catchError(response => {
                    if (response.url.includes('/draft')) {
                        if (response.url.includes('/draft/uuid')) {
                            this.router.navigateByUrl('/error');
                        }
                        throw new HttpErrorResponse({
                            error: response.message,
                            headers: response.headers,
                            status: 500,
                            statusText: 'Warning',
                            url: response.url
                        });
                    } else {
                        if (!response.url.includes('/address') &&
                            !response.url.includes('/authentication/user/profile')) {
                            this.router.navigateByUrl('/error');
                        }
                        throw new HttpErrorResponse({
                            error: response.message,
                            headers: response.headers,
                            status: 500,
                            statusText: 'Warning',
                            url: response.url
                        });
                    }
                })
            );
        }

        const token = this.tokenService.getToken();

        // Be careful not to overwrite an existing header of the same name.
        if (token !== null && !req.headers.has('X-XSRF-TOKEN')) {
            req = req.clone({headers: req.headers.set('X-XSRF-TOKEN', token)});
        }
        return next.handle(req).pipe(
            catchError(response => {
                if (!response.url.includes('/draft/form')) {
                    this.router.navigateByUrl('/error');
                }
                throw new HttpErrorResponse({
                    error: response.message,
                    headers: response.headers,
                    status: 500,
                    statusText: 'Warning',
                    url: response.url
                });
            })
        );
    }
}
