import { HttpClient, HttpErrorResponse, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { getConfig } from '../app-config';
import { AppConstants } from '../constants/app.constants';
import { FormConfig } from './form-config';
declare var $: any;

@Injectable({
    providedIn: 'root'
})
export class FormService {
    private readonly environment = getConfig()

    HTTPOptionsForText: object = {
        headers: new HttpHeaders({'Content-Type': 'application/json'}),
        responseType: 'text'
    };

    HTTPOptionsForTextSecure: object = {
        headers: new HttpHeaders({'Content-Type': 'application/json'}),
        responseType: 'text',
        withCredentials: true
    };

    constructor(private readonly httpClient: HttpClient) {
    }

    // after submit, handle the redirect
    submit(data: any, secured: boolean, form: string, stage: string, uuid: string): Observable<any> {
        const path = secured ? '/secure' : '';
        // Voor cross domain request moeten we withCredentials zetten om access token mee te sturen.
        if (secured && this.environment.environmentname === 'dev') {
            return this.httpClient.post(`${this.environment.formStoreUrl}${path}/submission/submit/${stage}/${form}/${uuid}`, data, {withCredentials: true});
        }
        return this.httpClient.post(`${this.environment.formStoreUrl}${path}/submission/submit/${stage}/${form}/${uuid}`, data);
    }

    setuuid(): Observable<any> {
        if (this.environment.environmentname === 'dev') {
            return this.httpClient.get(`${this.environment.formStoreUrl}/config/setuuid`, this.HTTPOptionsForTextSecure);
        }
        return this.httpClient.get<any>(`${this.environment.formStoreUrl}/config/setuuid`, this.HTTPOptionsForText);
    }

    enrichPaymentRequest(amount: number, uuid: string, orderid: string, tokenPayment: boolean): Observable<any>{
        const jsonData: any = {};
        const number = Math.round(amount * 100);
        jsonData['amount'] = number.toString();
        jsonData['orderid'] = orderid;
        jsonData['com'] = orderid;
        const type = (tokenPayment) ? 'token' : 'form';
        return this.httpClient.post<any>(`${this.environment.formStoreUrl}/payment/calculate/hash/${type}/` + uuid, jsonData);
    }

    getPaymentDetails(token: string): Observable<any>{
        return this.httpClient.get<any>(`${this.environment.proxyUrl}/payment/token/read?token=` + token);
    }

    // save draft when secure form
    draft(data: any): Observable<any> {
        if (this.environment.environmentname === 'dev') {
            return this.httpClient.post(`${this.environment.formStoreUrl}/secure/draft/form`, data, {responseType: 'text', withCredentials: true});
        }
        return this.httpClient.post(`${this.environment.formStoreUrl}/secure/draft/form`, data, {responseType: 'text'});
    }

    // save draft with uuid
    draftUuid(data: any, secured: boolean): Observable<any> {
        const path = secured ? '/secure' : '';
        if (secured && this.environment.environmentname === 'dev') {
            return this.httpClient.post(`${this.environment.formStoreUrl}${path}/draft/uuid`, data, {responseType: 'text', withCredentials: true});
        }
        return this.httpClient.post(`${this.environment.formStoreUrl}${path}/draft/uuid`, data, {responseType: 'text'});
    }

    // save draft with uuid
    draftPaymentUuid(data: any): Observable<any> {
        if (this.environment.environmentname === 'dev') {
            return this.httpClient.post(`${this.environment.formStoreUrl}/draft/payment/uuid`, data, {responseType: 'text', withCredentials: true});
        }
        return this.httpClient.post(`${this.environment.formStoreUrl}/draft/payment/uuid`, data, {responseType: 'text'});
    }


    findDraftPayment(uuid: string | null): Observable<any> {
        if (this.environment.environmentname === 'dev') {
            return this.httpClient.get(`${this.environment.formStoreUrl}/draft/payment/uuid/` + uuid , {withCredentials: true});
        }
        return this.httpClient.get(`${this.environment.formStoreUrl}/draft/payment/uuid/` + uuid);
    }

    // only secure forms can have draft submissions
    findDraft(form: string) {
        if (this.environment.environmentname === 'dev') {
            return this.httpClient.get(`${this.environment.formStoreUrl}/secure/draft/` + form, {withCredentials: true});
        }
        return this.httpClient.get(`${this.environment.formStoreUrl}/secure/draft/` + form);
    }

    // get all stages
    getStages(): Observable<any>{
        return this.httpClient.get(`${this.environment.formStoreUrl}/stages`)
            .pipe(
                catchError(this.handleError)
            );
    }

    getStageForms(stage: string): Observable<any>{
        return this.httpClient.get(`${this.environment.formStoreUrl}/stage/` + stage)
            .pipe(
                catchError(this.handleError)
            );
    }

    getFormDefinition(stage: string, form: string): Observable<any>{
        return this.httpClient.get(`${this.environment.formStoreUrl}/` + stage + "?form=" + form)
            .pipe(
                catchError(this.handleError)
            );
    }

    // TOD0: check if this is still needed
    afterSuccessfulPaymentSubmission(uuid: string | null): Observable<any>{
        return this.httpClient.get(`${this.environment.formStoreUrl}/submission/submit?uuid=` + uuid)
            .pipe(
                catchError(this.handleError)
            );
    }

    findFormConfig(formName: string): Observable<any>{
        return this.httpClient.get(`${this.environment.formStoreUrl}/config/` + formName);
    }

    findFormConfigEmployee(): Observable<any>{
        if (this.environment.environmentname === 'dev') {
            return this.httpClient.get(`${this.environment.formStoreUrl}/secure/config/employee`, {withCredentials: true});
        }
        return this.httpClient.get(`${this.environment.formStoreUrl}/secure/config/employee`);
    }

    findReferenceSequence(): Observable<any>{
        return this.httpClient.get(`${this.environment.formStoreUrl}/config/reference/sequence`);
    }

    // eslint-disable-next-line
    handleError(error: HttpErrorResponse) {
        let errorMessage = 'Unknown error!';
        if (error.error instanceof ErrorEvent) {
            // Client-side errors
            errorMessage = `Error: ${error.error.message}`;
        } else {
            // Server-side errors
            errorMessage = `Error Code: ${error.status}\nMessage: ${error.message}`;
        }
        return throwError(errorMessage);
    }

    // the callback after a form submission or logout
    doCallback(): void {
        const formConfig: FormConfig | null = this.getFormConfig();
        if (formConfig) {
            // remove authentication form of current form??
            localStorage.removeItem(AppConstants.FORM_CONFIG);
            if (typeof formConfig.callBackUrl === 'string') {
                window.location.href = formConfig.callBackUrl;
            }
        }else{
            window.location.href = this.environment.defaultCallbackUrl;
        }
    }

    getFormConfig(): FormConfig | null{
        const jsonFormAuthentication = localStorage.getItem(AppConstants.FORM_CONFIG);
        if (jsonFormAuthentication) {
            return JSON.parse(jsonFormAuthentication);
        }

        return null;
    }

    public doPayment(amount: number, uuid: string, reference: string, formTitle: string, tokenPayment: boolean, payment: any): void{
        const orderId = reference + ' - ' + formTitle;

        // Als we al een betaalobject hebben, betekent dat dat de hash al bepaald is.
        // We kunnen direct door met betalen.
        if (!payment) {
            this.enrichPaymentRequest(amount, uuid, orderId.substring(0, 38), tokenPayment).subscribe(result => {
                this.sendPaymentToIngenico(result, orderId, amount, uuid, reference);
            });
        } else {
            this.sendPaymentToIngenico(payment, orderId, amount, uuid, reference);
        }
    }

    private sendPaymentToIngenico(result: any, orderId: string, amount: number, uuid: string, reference: string): void {
        const form = $('<form></form>');

        form.attr('METHOD', 'post');
        form.attr('id', 'form1');
        form.attr('name', 'form1');
        form.attr('ACTION', result.formPostUrl);

        // add dynamic template
        if (result.dynamicTemplate) {
            const fieldTP = $('<input></input>');
            fieldTP.attr('TYPE', 'hidden');
            fieldTP.attr('NAME', 'TP');
            fieldTP.attr('VALUE', result.dynamicTemplate);
            form.append(fieldTP);
        }

        if (result.pspId) {
            const field = $('<input></input>');
            field.attr('TYPE', 'hidden');
            field.attr('NAME', 'PSPID');
            field.attr('VALUE', result.pspId);
            form.append(field);
        }
        if (result.acceptUrl) {
            const field = $('<input></input>');
            field.attr('TYPE', 'hidden');
            field.attr('NAME', 'ACCEPTURL');
            field.attr('VALUE', result.acceptUrl);
            form.append(field);
        }
        if (result.exceptionUrl) {
            const field = $('<input></input>');
            field.attr('TYPE', 'hidden');
            field.attr('NAME', 'EXCEPTIONURL');
            field.attr('VALUE', result.exceptionUrl);
            form.append(field);
        }
        if (result.declineUrl) {
            const field = $('<input></input>');
            field.attr('TYPE', 'hidden');
            field.attr('NAME', 'DECLINEURL');
            field.attr('VALUE', result.declineUrl);
            form.append(field);
        }
        if (result.cancelUrl) {
            const field = $('<input></input>');
            field.attr('TYPE', 'hidden');
            field.attr('NAME', 'CANCELURL');
            field.attr('VALUE', result.cancelUrl);
            form.append(field);
        }

        // form kenmerk
        const field2 = $('<input></input>');
        field2.attr('TYPE', 'hidden');
        field2.attr('NAME', 'ORDERID');
        field2.attr('VALUE', orderId.substring(0, 38));
        form.append(field2);

        const field3 = $('<input></input>');
        field3.attr('TYPE', 'hidden');
        field3.attr('NAME', 'AMOUNT');
        field3.attr('VALUE', Math.round(amount * 100));
        form.append(field3);

        // Order description
        const field4a = $('<input></input>');
        field4a.attr('TYPE', 'hidden');
        field4a.attr('NAME', 'COM');
        field4a.attr('VALUE', reference.replace('.', ''));
        form.append(field4a);

        // PARAMVAR with uuid for PostSale
        const field5 = $('<input></input>');
        field5.attr('TYPE', 'hidden');
        field5.attr('NAME', 'PARAMVAR');
        field5.attr('VALUE', uuid);
        form.append(field5);

        if (result.currency) {
            const field4 = $('<input></input>');
            field4.attr('TYPE', 'hidden');
            field4.attr('NAME', 'CURRENCY');
            field4.attr('VALUE', result.currency);
            form.append(field4);
        }
        if (result.hashSign) {
            const field4 = $('<input></input>');
            field4.attr('TYPE', 'hidden');
            field4.attr('NAME', 'SHASIGN');
            field4.attr('VALUE', result.hashSign);
            form.append(field4);
        }

        if (result.language) {
            const field5 = $('<input></input>');
            field5.attr('TYPE', 'hidden');
            field5.attr('NAME', 'LANGUAGE');
            field5.attr('VALUE', result.language);
            form.append(field5);
        }

        // The form needs to be a part of the document in
        // order for us to be able to submit it.
        $(document.body).append(form);
        form.submit();
    }


    getCallbackUrl(): string {
        const formConfig: FormConfig | null = this.getFormConfig();
        if (formConfig) {
            // remove authentication form of current form??
            if (typeof formConfig.callBackUrl === 'string') {
                return formConfig.callBackUrl;
            }
        }
        return getConfig().defaultCallbackUrl;
    }

    getPdfUrl(secured: boolean, uuid: string, reference: string, formTitle: string): string {
        const path = secured ? '/secure' : '';
        return `${getConfig().formStoreUrl}${path}/pdf/${uuid}/${reference}/${formTitle}`;
    }
}
