import {Component, OnInit} from '@angular/core';
import {ActivatedRoute} from '@angular/router';
import {FormService} from '../service/form.service';
import {AppConstants} from '../constants/app.constants';
import {Title} from '@angular/platform-browser';

@Component({
    selector: 'app-stage-component',
    templateUrl: './stage.component.html',
    styleUrls: ['./stage.component.scss']
})
export class StageComponent implements OnInit {
    title = AppConstants.TITLE_PREFIX + 'Stages';
    forms: any[] = [];
    dataloaded = false;
    stage: string = '';

    constructor( formService: FormService, public route: ActivatedRoute, private titleService: Title) {
        this.route.queryParams
            .subscribe(params => {
                formService.getStageForms(params.stage).subscribe((result: any) => {
                    this.stage = params.stage;
                    result.forEach((form: any) => {
                        this.forms.push(form);
                    });
                    this.dataloaded = true;
                });
            });

    }

    ngOnInit(): void {
        this.titleService.setTitle(this.title);
    }
}
