import {Component, OnInit} from '@angular/core';
import {FormService} from '../service/form.service';
import { Title } from '@angular/platform-browser';
import {AppConstants} from '../constants/app.constants';
@Component({
    selector: 'app-home',
    templateUrl: './home.component.html',
    styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {
    title = AppConstants.TITLE_PREFIX + 'Homepagina';
    stages: string[] = [];
    dataloaded = false;

    constructor(private formService: FormService, private titleService: Title) {
    }

    ngOnInit(): void {
        this.titleService.setTitle(this.title);
        this.formService.getStages().subscribe((result: any) => {
            result.forEach((stage: any) => {
                this.stages.push(stage.name);
            });
            this.dataloaded = true;
        });

    }
}
